import sharp from 'sharp';
import {validateMedia} from './backend/media-validation.mjs';
const png=await sharp({create:{width:8,height:8,channels:3,background:'#123456'}}).png().toBuffer();
if((await validateMedia(png,'image/png')).type!=='image')throw Error('image-validation');
const samples=8000,wav=Buffer.alloc(44+samples*2);
wav.write('RIFF');wav.writeUInt32LE(wav.length-8,4);wav.write('WAVEfmt ',8);wav.writeUInt32LE(16,16);wav.writeUInt16LE(1,20);wav.writeUInt16LE(1,22);wav.writeUInt32LE(16000,24);wav.writeUInt32LE(32000,28);wav.writeUInt16LE(2,32);wav.writeUInt16LE(16,34);wav.write('data',36);wav.writeUInt32LE(samples*2,40);
for(let i=0;i<samples;i++)wav.writeInt16LE(Math.round(Math.sin(i*2*Math.PI*440/16000)*1000),44+i*2);
const audio=await validateMedia(wav,'audio/wav');if(audio.type!=='audio'||audio.durationMs!==500)throw Error('audio-validation');
console.log('Linux: imagen PNG y audio WAV decodificados; sin red ni Firebase. No prueba captura de micrófono.');
